<template>
<div class="page-container dns-page">
  <header class="page-header dns-header"><div><router-link to="/" class="back-link">‹ 返回控制面板</router-link><h2>DNS 管理</h2><p>集中查看和维护 Cloudflare 区域中的 DNS 记录。</p></div><button class="btn btn-primary" :disabled="!zoneID" @click="openCreate">＋ 添加记录</button></header>
  <section class="workspace">
    <div class="toolbar"><label><span class="caption-mono">区域</span><select v-model="zoneID" class="vercel-input" :disabled="zonesLoading"><option value="" disabled>{{ zonesLoading?'正在加载区域...':'选择一个区域' }}</option><option v-for="z in zones" :key="z.id" :value="z.id">{{ z.name }}</option></select></label><label><span class="caption-mono">搜索记录</span><input v-model="search" class="vercel-input" placeholder="名称、内容或类型" :disabled="!zoneID"></label><button class="refresh" :disabled="!zoneID||loading" title="刷新" @click="loadRecords">↻</button></div>
    <div v-if="loading" class="state"><i class="loader"></i><strong>正在读取 DNS 记录</strong><span>这通常只需几秒钟</span></div>
    <div v-else-if="loadError" class="state error"><strong>无法加载 DNS 记录</strong><span>{{ loadError }}</span><button class="btn btn-secondary" @click="loadRecords">重试</button></div>
    <div v-else-if="!zoneID" class="state"><b>DNS</b><strong>先选择一个区域</strong><span>选择后即可查看和管理该区域的记录。</span></div>
    <div v-else-if="!filtered.length" class="state"><b>0</b><strong>{{ search?'没有匹配的记录':'尚无 DNS 记录' }}</strong><span>{{ search?'尝试更换搜索关键词。':'添加第一条记录以开始解析流量。' }}</span></div>
    <div v-else class="table-wrap"><table><thead><tr><th>类型</th><th>名称</th><th>内容</th><th>代理</th><th>TTL</th><th>操作</th></tr></thead><tbody><tr v-for="r in filtered" :key="r.id"><td><em>{{ r.type }}</em></td><td><code>{{ r.name }}</code></td><td class="content"><small v-if="r.type==='MX'">优先级 {{ r.priority??0 }}</small><code :title="r.content">{{ r.content }}</code></td><td><span v-if="proxyEligible(r.type)" class="proxy" :class="{on:r.proxied}">● {{ r.proxied?'已代理':'仅 DNS' }}</span><span v-else class="muted">不适用</span></td><td>{{ ttlLabel(r.ttl) }}</td><td><div class="actions"><button v-if="editableType(r.type)" title="编辑" @click="openEdit(r)">✎</button><span v-else class="muted">只读</span><button class="danger" title="删除" @click="confirmDelete(r)">×</button></div></td></tr></tbody></table><footer>显示 {{ filtered.length }} 条记录<span v-if="search">，共 {{ records.length }} 条</span></footer></div>
  </section>
  <n-modal v-model:show="editorOpen" :mask-closable="!saving" preset="card" :title="editing?'编辑 DNS 记录':'添加 DNS 记录'" class="record-modal"><div class="editor"><label><span>记录类型</span><n-select v-model:value="form.type" :options="typeOptions" @update:value="typeChanged"/></label><label><span>名称</span><n-input v-model:value="form.name" placeholder="例如 www 或 example.com"/></label><label class="wide"><span>{{ contentLabel }}</span><n-input v-model:value="form.content" type="textarea" :autosize="{minRows:form.type==='TXT'?3:1,maxRows:6}" :placeholder="contentPlaceholder"/></label><label v-if="form.type==='MX'"><span>优先级</span><n-input-number v-model:value="form.priority" :min="0" :max="65535"/></label><label><span>TTL</span><n-select v-model:value="form.ttl" :options="ttlOptions"/></label><label v-if="proxyEligible(form.type)" class="switch"><span>代理状态</span><n-switch v-model:value="form.proxied"><template #checked>已代理</template><template #unchecked>仅 DNS</template></n-switch></label></div><p v-if="formError" class="form-error">{{ formError }}</p><template #footer><div class="modal-actions"><button class="btn btn-secondary" :disabled="saving" @click="editorOpen=false">取消</button><button class="btn btn-primary" :disabled="saving" @click="save">{{ saving?'正在保存...':editing?'保存更改':'添加记录' }}</button></div></template></n-modal>
</div>
</template>
<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {NInput,NInputNumber,NModal,NSelect,NSwitch,useDialog,useMessage} from 'naive-ui'
import {createDNSRecord,deleteDNSRecord,listDNSRecords,listZones,updateDNSRecord,type DNSRecord,type DNSRecordInput,type DNSRecordType,type Zone} from '../api'
type ZoneDNSRecord=DNSRecord&{zone_id:string}
const message=useMessage(),dialog=useDialog(); const zones=ref<Zone[]>([]),zoneID=ref(''),records=ref<ZoneDNSRecord[]>([]),search=ref(''),zonesLoading=ref(false),loading=ref(false),loadError=ref(''),editorOpen=ref(false),saving=ref(false),editing=ref<ZoneDNSRecord|null>(null),editorZoneID=ref(''),formError=ref(''); let loadGeneration=0
const blank=():DNSRecordInput=>({type:'A',name:'',content:'',ttl:1,proxied:false}); const form=ref<DNSRecordInput>(blank())
const typeOptions=['A','AAAA','CNAME','TXT','MX'].map(value=>({label:value,value})); const ttlOptions=[{label:'自动',value:1},...[60,120,300,600,1800,3600,7200,18000,43200,86400].map(value=>({label:ttlLabel(value),value}))]
const filtered=computed(()=>{const q=search.value.trim().toLowerCase();return q?records.value.filter(r=>[r.type,r.name,r.content].some(v=>String(v).toLowerCase().includes(q))):records.value})
const contentLabel=computed(()=>form.value.type==='MX'?'邮件服务器':form.value.type==='TXT'?'文本内容':'目标内容'); const contentPlaceholder=computed(()=>({A:'例如 192.0.2.1',AAAA:'例如 2001:db8::1',CNAME:'例如 target.example.com',TXT:'输入 TXT 记录内容',MX:'例如 mail.example.com'}[form.value.type]))
function editableType(t:string):t is DNSRecordType{return ['A','AAAA','CNAME','TXT','MX'].includes(t)} function proxyEligible(t:string){return ['A','AAAA','CNAME'].includes(t)} function ttlLabel(t:number){return t===1?'自动':t<3600?`${t/60} 分钟`:t<86400?`${t/3600} 小时`:`${t/86400} 天`} function err(e:any){return e.response?.data?.error||e.response?.data?.message||e.message||'未知错误'}
async function loadZones(){zonesLoading.value=true;try{zones.value=(await listZones()).data;if(zones.value.length)zoneID.value=zones.value[0].id}catch(e){message.error('区域加载失败: '+err(e))}finally{zonesLoading.value=false}}
async function loadRecords(){const requestedZone=zoneID.value;if(!requestedZone)return;const generation=++loadGeneration;loading.value=true;loadError.value='';try{const data=(await listDNSRecords(requestedZone)).data;if(generation!==loadGeneration||zoneID.value!==requestedZone)return;records.value=data.map(record=>({...record,zone_id:requestedZone}))}catch(e){if(generation!==loadGeneration||zoneID.value!==requestedZone)return;records.value=[];loadError.value=err(e)}finally{if(generation===loadGeneration)loading.value=false}}
function openCreate(){editing.value=null;editorZoneID.value=zoneID.value;form.value=blank();formError.value='';editorOpen.value=true} function openEdit(r:ZoneDNSRecord){if(!editableType(r.type))return;editing.value=r;editorZoneID.value=r.zone_id;form.value={type:r.type,name:r.name,content:r.content,ttl:r.ttl,...(proxyEligible(r.type)?{proxied:!!r.proxied}:{}),...(r.type==='MX'?{priority:r.priority??0}:{})};formError.value='';editorOpen.value=true}
function typeChanged(t:DNSRecordType){form.value.proxied=proxyEligible(t)?false:undefined;form.value.priority=t==='MX'?0:undefined} function payload():DNSRecordInput{return{type:form.value.type,name:form.value.name.trim(),content:form.value.content.trim(),ttl:form.value.ttl,...(proxyEligible(form.value.type)?{proxied:!!form.value.proxied}:{}),...(form.value.type==='MX'?{priority:form.value.priority??0}:{})}}
async function save(){formError.value=!form.value.name.trim()?'请输入记录名称':!form.value.content.trim()?'请输入记录内容':form.value.type==='MX'&&form.value.priority===undefined?'请输入 MX 优先级':'';if(formError.value)return;const targetZone=editorZoneID.value;if(!targetZone){formError.value='区域已失效，请关闭窗口后重试';return}saving.value=true;try{editing.value?await updateDNSRecord(targetZone,editing.value.id,payload()):await createDNSRecord(targetZone,payload());message.success(editing.value?'记录已更新':'记录已添加');editorOpen.value=false;if(zoneID.value===targetZone)await loadRecords()}catch(e){formError.value=err(e)}finally{saving.value=false}}
function confirmDelete(r:ZoneDNSRecord){const targetZone=r.zone_id;dialog.warning({title:'删除 DNS 记录',content:`确定删除 ${r.type} 记录“${r.name}”吗？此操作无法撤销。`,positiveText:'确认删除',negativeText:'取消',async onPositiveClick(){try{await deleteDNSRecord(targetZone,r.id);message.success('记录已删除');if(zoneID.value===targetZone)await loadRecords()}catch(e){message.error('删除失败: '+err(e));return false}}})}
watch(zoneID,()=>{loadGeneration++;loading.value=false;records.value=[];loadError.value='';search.value='';loadRecords()});onMounted(loadZones)
</script>
<style scoped>
.dns-page{max-width:1440px}.dns-header{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;max-width:none}.workspace{overflow:hidden;background:var(--color-canvas);border:1px solid var(--color-hairline);border-radius:var(--radius-lg);box-shadow:0 1px 2px rgba(58,47,34,.05)}.toolbar{display:grid;grid-template-columns:minmax(220px,360px) minmax(260px,1fr) 42px;gap:12px;align-items:end;padding:16px 24px;background:var(--color-canvas-soft);border-bottom:1px solid var(--color-hairline)}.toolbar label,.editor label{display:flex;flex-direction:column;gap:6px;min-width:0}.toolbar .caption-mono{color:var(--color-mute)}.refresh{height:42px;color:var(--color-body);font-size:20px;background:var(--color-canvas);border:1px solid var(--color-btn-secondary-border);border-radius:var(--radius-sm);cursor:pointer}.refresh:disabled{opacity:.45}.table-wrap{overflow-x:auto}table{width:100%;min-width:880px;border-collapse:collapse;table-layout:fixed}th{padding:11px 14px;color:var(--color-mute);font:600 10px var(--font-mono);text-align:left;letter-spacing:.08em;background:var(--color-canvas-soft);border-bottom:1px solid var(--color-hairline)}td{padding:13px 14px;color:var(--color-body);font-size:13px;border-bottom:1px solid var(--color-hairline)}tbody tr:hover{background:var(--color-canvas-soft)}th:first-child{width:70px}th:nth-child(2){width:20%}th:nth-child(4){width:105px}th:nth-child(5){width:90px}th:last-child{width:82px}td code{display:block;overflow:hidden;color:var(--color-ink);font:12px var(--font-mono);text-overflow:ellipsis;white-space:nowrap}td em{display:inline-flex;min-width:42px;justify-content:center;padding:3px 5px;color:var(--color-ink);font:700 11px var(--font-mono);font-style:normal;background:var(--color-canvas-soft-2);border:1px solid var(--color-hairline);border-radius:6px}.content small{display:block;color:var(--color-mute)}.proxy{white-space:nowrap}.proxy.on{color:var(--color-warning)}.muted{color:var(--color-mute)}.actions{display:flex;justify-content:flex-end}.actions button{width:30px;height:30px;color:var(--color-body);background:none;border:0;border-radius:6px;cursor:pointer}.actions button:hover{background:var(--color-canvas-soft-2)}.actions .danger:hover{color:var(--color-error)}footer{padding:10px 14px;color:var(--color-mute);font-size:12px;background:var(--color-canvas-soft)}.state{display:flex;min-height:320px;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:36px;color:var(--color-mute);text-align:center}.state strong{color:var(--color-ink)}.state b{display:grid;width:48px;height:48px;place-items:center;color:var(--color-link);font:700 13px var(--font-mono);border:1px solid var(--color-hairline);border-radius:50%}.state.error strong{color:var(--color-error)}.loader{width:22px;height:22px;border:2px solid var(--color-hairline);border-top-color:var(--color-link);border-radius:50%;animation:spin .8s linear infinite}.editor{display:grid;grid-template-columns:150px 1fr;gap:16px}.editor label>span{color:var(--color-ink);font-size:13px;font-weight:600}.editor .wide{grid-column:1/-1}.switch{justify-content:flex-end}.form-error{padding:10px;color:var(--color-result-error-text);font-size:13px;background:var(--color-result-error-bg);border:1px solid var(--color-result-error-border);border-radius:6px}.modal-actions{display:flex;justify-content:flex-end;gap:8px}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:768px){.dns-header{align-items:stretch;flex-direction:column}.dns-header .btn{align-self:flex-start}.toolbar{grid-template-columns:1fr 42px}.toolbar label:first-child{grid-column:1/-1}.editor{grid-template-columns:1fr}.editor .wide{grid-column:auto}}@media(max-width:480px){.dns-header .btn{width:100%;justify-content:center}.toolbar{padding:12px}.modal-actions .btn{flex:1;justify-content:center}}
</style>
